{
  "story": "A decision tree partitions feature space into orthogonal regions. Each step adds a splitting threshold on one feature to minimize impurity, separating classes until regions become pure.",
  "aha": {
    "stateId": "split2",
    "observation": "Adding a second split subdivides the existing feature space into four distinct regions, isolating the minority class."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "canvas",
      "kind": "fixed-picture",
      "bind": {
        "regions": "variant.regions",
        "completedBefore": "inputs.stepIndex"
      }
    },
    {
      "id": "ghost",
      "kind": "previous-state-ghost",
      "bind": {
        "regions": "previous.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "values": "state.active"
      }
    },
    {
      "id": "metrics",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Tree Step",
      "options": [
        "Root",
        "Split 1",
        "Split 2",
        "Pure"
      ]
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "regions": [
          {
            "id": "r1",
            "label": "Entire Feature Space",
            "kind": "box",
            "values": ["x: 0-10", "y: 0-10"]
          }
        ],
        "states": [
          {
            "id": "root",
            "label": "Root",
            "short": "Start",
            "sentence": "All training points reside in one single unpartitioned region.",
            "why": "Initialization",
            "active": ["r1"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "gini",
                "label": "Gini Impurity",
                "value": "0.50"
              }
            ]
          },
          {
            "id": "split1",
            "label": "First Split",
            "short": "X Split",
            "sentence": "A vertical threshold at x = 5 divides the space into two halves.",
            "why": "First feature threshold",
            "active": ["r1"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "gini",
                "label": "Gini Impurity",
                "value": "0.32"
              }
            ]
          },
          {
            "id": "split2",
            "label": "Second Split",
            "short": "Y Split",
            "sentence": "A horizontal threshold at y = 4 subdivides the left region.",
            "why": "Second feature threshold",
            "active": ["r1"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "gini",
                "label": "Gini Impurity",
                "value": "0.12"
              }
            ]
          },
          {
            "id": "pure",
            "label": "Leaf Nodes",
            "short": "Pure",
            "sentence": "Final regions successfully separate the classes with minimum impurity.",
            "why": "Completion",
            "active": ["r1"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "gini",
                "label": "Gini Impurity",
                "value": "0.00"
              }
            ]
          }
        ]
      }
    ]
  }
}
